H.background();
// IMF type: 1 -> LDF (London dispersion), 2 -> dipole-dipole, 3 -> hydrogen bond
let k = Math.round(P.imf);
if (k < 1) k = 1; if (k > 3) k = 3;
const data = {
  1: { name: "London dispersion (LDF)", strength: 1, ex: "Cl₂  bp ≈ −34 °C", color: H.colors.accent },
  2: { name: "Dipole–dipole", strength: 2, ex: "H₂S  bp ≈ −60 °C", color: H.colors.violet },
  3: { name: "Hydrogen bond", strength: 3, ex: "H₂O  bp = 100 °C", color: H.colors.warn }
};
const d = data[k];
// two molecules vibrating; closer & tighter coupling for stronger IMF
const cx = H.W / 2, cy = 250;
const baseSep = 220 - d.strength * 30;
// stronger IMF -> smaller thermal wobble (more held together)
const amp = 30 / d.strength;
const wob = amp * Math.sin(t * 2.0);
const x1 = cx - baseSep / 2 - wob, x2 = cx + baseSep / 2 + wob;
// molecule 1
H.circle(x1, cy, 30, { fill: H.colors.panel, stroke: d.color, width: 3 });
H.circle(x2, cy, 30, { fill: H.colors.panel, stroke: d.color, width: 3 });
// partial charges shown for dipole / H-bond
if (k >= 2) {
  H.text("δ+", x1 - 6, cy, { color: H.colors.good, size: 13, align: "center", baseline: "middle" });
  H.text("δ−", x1 + 14, cy, { color: H.colors.warn, size: 13, align: "center", baseline: "middle" });
  H.text("δ+", x2 - 6, cy, { color: H.colors.good, size: 13, align: "center", baseline: "middle" });
  H.text("δ−", x2 + 14, cy, { color: H.colors.warn, size: 13, align: "center", baseline: "middle" });
}
// the IMF link between them (dashed), thickness ~ strength
const dash = k === 3 ? [6, 5] : [4, 6];
for (let i = 0; i < d.strength; i++) {
  const off = (i - (d.strength - 1) / 2) * 7;
  H.line(x1 + 30, cy + off, x2 - 30, cy + off, { color: d.color, width: 2, dash: dash });
}
H.text("attraction", cx, cy - 24, { color: d.color, size: 12, align: "center" });
// boiling-point thermometer bar (relative), animated pulse
const bpRel = d.strength / 3; // 0..1 schematic
const barX = 120, barTop = 360, barBot = 470, barW = 50;
H.rect(barX, barTop, barW, barBot - barTop, { stroke: H.colors.grid, width: 1 });
const fill = (barBot - barTop) * bpRel;
const puls = 0.95 + 0.05 * Math.sin(t * 3);
H.rect(barX, barBot - fill * puls, barW, fill * puls, { fill: d.color });
H.text("boiling point", barX + barW / 2, barBot + 18, { color: H.colors.sub, size: 12, align: "center" });
H.text("Intermolecular forces set boiling point", 24, 30, { color: H.colors.ink, size: 18, weight: 700 });
H.text("Stronger IMF → more energy to separate molecules → higher b.p.", 24, 52, { color: H.colors.sub, size: 13 });
H.text(d.name + "   |   " + d.ex, 24, 74, { color: d.color, size: 14, weight: 700 });
// ranking legend
H.legend([
  { label: "LDF (weakest)", color: H.colors.accent },
  { label: "dipole–dipole", color: H.colors.violet },
  { label: "H-bond (strongest)", color: H.colors.warn }
], H.W - 230, 110);
